INSERT INTO item (id, title, summary, description, bgcolor, color, url, new_tab, sort_order, icon_id, category_id) VALUES (69, 'Xolo', 'Xolo est une passerelle LLM d''entreprise', '<p><a href="https://xolo.cadoles.com" rel="nofollow">Xolo</a> est une <strong>passerelle LLM d&#39;\nentreprise</strong>. Elle expose une API compatible OpenAI et fournit une interface web d&#39;\nadministration multi-tenant. Vous pouvez l&#39;\nutiliser pour acc&eacute;\nder &agrave;\n des mod&egrave;\nles de langage via vos applications ou outils habituels, tout en b&eacute;\nn&eacute;\nficiant d&#39;\nune gestion centralis&eacute;\ne des acc&egrave;\ns, des quotas et de la facturation.</p>', NULL, NULL, 'https://xolo.cadoles.com', true, 0, 484, 9);
